    private View chapterRow(int index){PdfReflow.ChapterItem c=chapters.get(index);LinearLayout row=u.row();row.setPadding(u.dp(12),u.dp(12),u.dp(4),u.dp(12));row.setBackground(theme.chipBackground(index==selectedChapter?theme.blueWash:theme.surface,index==selectedChapter?theme.accent:theme.edge,16));TextView number=u.text(String.format(Locale.ROOT,"%02d",index+1),17,true);number.setTextColor(theme.accent);row.addView(number,new LayoutParams(u.dp(38),-2));LinearLayout copy=u.column();TextView title=u.text(c.title,14,true);title.setMaxLines(2);copy.addView(title);u.gap(copy,6);JSONObject take=matchingTake(c);String state=take!=null?"Sẵn sàng · "+MobileUi.time((long)(take.optDouble("seconds")*1000)):"Chưa tạo";if(PlaybackService.running&&detailBook.optString("id").equals(PlaybackService.bookId)&&c.title.equals(PlaybackService.chapterTitle))state=PlaybackService.paused?"Đã tạm dừng":"Đang nghe";copy.addView(u.text(state+" · "+MobileUi.chars(c.text.length()),11,false));row.addView(copy,new LayoutParams(0,-2,1));row.addView(u.icon("more","Tùy chọn "+c.title,v->chapterOptions(index)),new LayoutParams(u.dp(48),u.dp(48)));row.setSelected(index==selectedChapter);row.setFocusable(true);row.setOnClickListener(v->{selectedChapter=index;if(selectionLabel!=null)selectionLabel.setText(c.title);chapterAdapter.notifyDataSetChanged();});row.setContentDescription(c.title+", "+state);return row;}
    private JSONObject matchingTake(PdfReflow.ChapterItem c){String hash=BookStore.hash(c.text);for(JSONObject take:takes)if(hash.equals(take.optString("textHash"))&&detailBook.optString("voice").equals(take.optString("voice"))&&detailBook.optBoolean("bilingual")==take.optBoolean("bilingual")&&(!detailBook.optBoolean("bilingual")||BookStore.contentSignature(detailBook).equals(take.optString("contentSignature"))))return take;return null;}
